 touches:["q"],
 reponse:[["load average: 0.44, 0.49, 0.27", "La charge moyenne sur 1, 5 et 15 minutes"], ["Tasks:  59 total,   1 running,  58 sleeping,   0 stopped,   0 zombie", "59 programmes : 1 travaille, 58 attendent"], ["MiB Mem :   7814.2 total,   5902.1 free,    782.0 used,   1300.5 buff/cache", "La mémoire : 7,8 Go en tout, 782 Mo utilisés"], ["    PID USER      PR  NI    VIRT    RES    SHR S  %CPU  %MEM     TIME+ COMMAND", "Puis un programme par ligne"]],
