 reponse:[["adduser/noble,now 3.137ubuntu1 all [installed,automatic]", "Une ligne de apt list --installed : le paquet adduser est installé"], ["WARNING: apt does not have a stable CLI interface. Use with caution in scripts.", "apt t'avertit : dans un script, la documentation conseille apt-get, qui change moins d'une version à l'autre"]],
