 quand:"Quand tu as fini de travailler, ou pour repartir propre.",
 flux:["dk-compose-up", "dk-compose-down"],
 lignes:[["docker compose down", "arrête et supprime conteneurs et réseau, garde les volumes"], ["docker compose down -v", "supprime AUSSI les volumes, donc les données"], ["docker volume ls", "vérifie ce qui reste"]],
 reponse:[[" Container boutique-web-1 Removed", "Le conteneur est supprimé"], [" Network boutique_default Removed", "Le réseau aussi"], ["local     boutique_pages", "Après down sans -v : le volume et ses données sont toujours là"], [" Volume boutique_pages Removed", "Après down -v : le volume est parti"]],
 pieges:[["docker compose down -v par habitude", "-v efface les données des volumes : une base entière peut partir. Ne l'utilise que pour tout jeter."], ["no configuration file provided: not found", "Tu n'es pas dans le dossier du projet."]],
