 pieges:[["Uncaught TypeError: Assignment to constant variable.", "Tu essaies de changer une const. Si la valeur doit changer, déclare-la avec let."], ["Uncaught SyntaxError: Identifier 'prenom' has already been declared", "Ce nom est déjà déclaré au même endroit de ton fichier. On déclare une variable une seule fois : ensuite, on l'utilise sans const ni let."], ["Uncaught ReferenceError: Awa is not defined", "Les guillemets manquent : sans eux, JavaScript cherche une variable nommée Awa. Écris \"Awa\"."]],
 mots:["string"],
 cherche:"variable ranger une valeur declarer une variable let const memoriser",
 defi:{consigne:"Range le texte Awa dans une constante nommée prenom.", ok:["^const prenom ?= ?([\"'`])Awa\\1 ?;?$"], fautes:[["^const prenom ?= ?Awa ?;?$", "Il manque les guillemets : \"Awa\". Sans eux, JavaScript cherche une variable nommée Awa."], ["^Const ", "JavaScript fait la différence entre majuscules et minuscules : const, en minuscules."], ["^(let|var) prenom", "Ça marche, mais la consigne demande une constante : const."]], essai:"const prenom = \"Awa\";"},
 doc:"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/const",
