 quand:"À chaque séance de travail, depuis le dossier du projet. Ctrl + C l'arrête.",
 lignes:[["php artisan serve", "démarre le serveur sur le port 8000"], ["php artisan serve --port=8080", "sur un autre port"], ["php artisan --version", "la version de Laravel du projet"]],
 reponse:[["INFO Server running on [http://127.0.0.1:8000].", "Ouvre cette adresse dans le navigateur"], ["Press Ctrl+C to stop the server", "Le terminal reste occupé tant que le serveur tourne"], ["Laravel Framework 13.37.0", "php artisan --version"]],
