 reponse:[["GET|HEAD produits/{id} .. ProduitController@show", "La méthode, l'adresse, puis le contrôleur et sa méthode"], ["GET|HEAD bonjour .. routes/web.php:10", "Une route avec fonction : le fichier et la ligne"], ["Showing [4] routes", "Le total"]],
