 reponse:[["Tu peux voter", "age vaut 20 : la condition est vraie"], ["Fin", "Revenu au bord, ce print s'exécute dans tous les cas"]],
 pieges:[["SyntaxError: expected ':'", "Les deux-points manquent à la fin de la ligne if."], ["IndentationError: expected an indented block after 'if' statement on line 1", "La ligne sous le if n'est pas décalée. Ajoute 4 espaces devant, ou appuie sur Tab dans VS Code."], ["SyntaxError: invalid syntax. Maybe you meant '==' or ':=' instead of '='?", "Un seul = range une valeur. Pour comparer : ==."]],
 mots:["indentation"],
