 pieges:[["isinstance(True, int) vaut True", "En Python, True compte comme un entier. Pour refuser un vrai ou faux, teste d'abord isinstance(x, bool)."], ["NameError: name 'string' is not defined", "Le type du texte s'écrit str, pas string."]],
