 reponse:[["\"id\": \"https://mon-coffre-awa.vault.azure.net/secrets/cle-ia/...\"", "L'adresse du secret dans le coffre, suivie de son numéro de version"]],
 pieges:[["Le nom du coffre est refusé", "De 3 à 24 caractères, lettres, chiffres et tirets, et unique dans le monde entier : il devient une adresse en vault.azure.net."], ["Accès refusé, même dans ton propre coffre", "Créer le coffre ne donne pas le droit d'y écrire. Il faut te donner le rôle Key Vault Secrets Officer avec az role assignment create. Le texte exact du refus peut varier."], ["Le nom reste pris après suppression", "Un coffre supprimé reste récupérable 90 jours par défaut (de 7 à 90, choisi à la création), et son nom reste pris pendant ce temps."]],
