 lignes:[["df.to_excel(\"bilan.xlsx\", index=False)","une feuille, nommée Sheet1 par défaut"],["df.to_excel(\"bilan.xlsx\", sheet_name=\"Bilan\", index=False)","tu choisis le nom de la feuille"],["with pd.ExcelWriter(\"rapport.xlsx\") as writer:","plusieurs feuilles dans un même classeur : ouvre un ExcelWriter. Attention, un fichier du même nom est écrasé"],["    ventes.to_excel(writer, sheet_name=\"Ventes\")","puis une ligne to_excel par feuille, décalée sous le with"]],
