 pieges:[["ModuleNotFoundError: No module named 'openpyxl'","Il manque openpyxl pour écrire le .xlsx : pip install openpyxl."],["TypeError: NDFrame.to_excel() takes 2 positional arguments but 3 positional arguments (and 1 keyword-only argument) were given","Le nom de la feuille se donne avec son mot-clé : sheet_name=\"Bilan\"."]],
