 defi:{consigne:"Enregistre df dans bilan.xlsx, sur une feuille nommée Bilan, sans l'index.", ok:["^df\\.to_excel\\( ?([\"'])bilan\\.xlsx\\1 ?, ?sheet_name ?= ?([\"'])Bilan\\2 ?, ?index ?= ?False ?\\)$","^df\\.to_excel\\( ?([\"'])bilan\\.xlsx\\1 ?, ?index ?= ?False ?, ?sheet_name ?= ?([\"'])Bilan\\2 ?\\)$"], fautes:[["^pd\\.to_excel\\(","to_excel appartient au tableau : df.to_excel(...)."],["\\bsheet ?=","Le paramètre s'appelle sheet_name."],["^df\\.to_csv\\(","to_csv écrit un .csv. Pour Excel : to_excel."],["^df\\.to_excel\\( ?[\"']bilan\\.xlsx[\"'] ?, ?[\"']Bilan","Le nom de la feuille se donne avec son mot-clé : sheet_name=\"Bilan\"."],["^df\\.to_excel\\( ?[\"']bilan\\.xlsx[\"'] ?, ?sheet_name ?= ?[\"']Bilan[\"'] ?\\)$","Il manque index=False : sinon la colonne des étiquettes de lignes part dans le classeur."]], essai:"df.to_excel(\"bilan.xlsx\", sheet_name=\"Bilan\", index=False)"},
