 defi:{consigne:"Quel bouton de l'onglet Accueil ouvre l'Éditeur Power Query ? Réponds en anglais.", ok:["^transform data$","^transformer les donn[ée]es$"], flags:"i", fautes:[["^get data","Get Data choisit une source. Pour ouvrir l'éditeur : Transform Data."],["^power query$","C'est le nom de l'outil. Le bouton s'appelle Transform Data."],["^close","Close & Apply referme l'éditeur. Pour l'ouvrir : Transform Data."]], essai:"Transform Data"},
