 lignes:[["Worksheets(\"Ventes\").Range(\"A1\").Value = \"Janvier\"","écrit sur la feuille Ventes, quelle que soit la feuille affichée"],["Worksheets(1).Range(\"A1\").Value = \"Janvier\"","la première feuille, par son numéro"],["Worksheets.Add","ajoute une nouvelle feuille au classeur"]],
