 defi:{consigne:"Écris la ligne qui met 0 dans la cellule A1 de la feuille Stock.", ok:["^((thisworkbook|activeworkbook)\\.)?(worksheets|sheets) ?\\( ?\"stock\" ?\\) ?\\. ?(range ?\\( ?\"a1\" ?\\)|cells ?\\( ?1 ?, ?(1|\"a\") ?\\))(\\.value)? ?= ?0$"], fautes:[["^worksheets ?\\( ?stock ?\\)","Le nom de la feuille se met entre guillemets : Worksheets(\"Stock\")."],["^worksheet ?\\(","Il manque le s : Worksheets, la collection de toutes les feuilles."],["^range ?\\( ?\"a1\" ?\\)","Sans préfixe, Range vise la feuille active. Commence par Worksheets(\"Stock\")."]], flags:"i", essai:"Worksheets(\"Stock\").Range(\"A1\").Value = 0"},
