 lignes:[["q()","quitte R, après la question sur l'enregistrement"],["q(save = \"no\")","quitte sans rien enregistrer et sans poser la question"]],
 reponse:[["Save workspace image? [y/n/c]:","y (oui) enregistre tes objets dans le fichier .RData, n (non) quitte sans enregistrer, c annule et te laisse dans R. En français : Sauver une image de la session ? [y/n/c]:. Posit conseille de ne pas l'enregistrer : ton script doit suffire à tout refaire"]],
 pieges:[["function (save = \"default\", status = 0, runLast = TRUE)","Tu as tapé q sans parenthèses : R affiche le code de la fonction au lieu de l'exécuter. Écris q()."],["Error in exit() : could not find function \"exit\"","exit n'existe pas en R. Pour quitter : q(), ou quit()."],["+","R attend la fin de ta commande : une parenthèse ou un guillemet n'est pas fermé. Termine la ligne, ou appuie sur Échap dans RStudio pour interrompre."]],
 mots:["prompt"],
