 defi:{consigne:"Quitte R sans enregistrer l'espace de travail.", ok:["^(q|quit)\\( ?(save ?= ?)?([\"'])no\\3 ?\\)$"], fautes:[["^(q|quit)\\( ?(save ?= ?)?no ?\\)$","Il manque les guillemets : save = \"no\". Sans eux, R cherche une variable nommée no."],["^(q|quit)$","Sans parenthèses, R affiche le code de la fonction au lieu de quitter : q(save = \"no\")."],["^exit\\(","exit n'existe pas en R. La fonction est q, ou quit."],["^Q\\(","R fait la différence entre majuscules et minuscules : q, en minuscule."]], essai:"q(save = \"no\")"},
