 reponse:[["[1] FALSE  TRUE FALSE","is.na(notes) : seule la deuxième valeur manque"],["[1] 10.5","mean(notes, na.rm = TRUE) : la moyenne de 12 et 9"]],
 pieges:[["[1] NA","mean(notes) sans na.rm = TRUE : une seule valeur manquante suffit, la moyenne devient inconnue."],["[1] NA NA NA","Tu as écrit notes == NA. NA n'est pas une valeur mais une marque : la comparaison donne NA partout. Utilise is.na(notes)."],["\"NA\"","Entre guillemets, \"NA\" est un texte de deux lettres, pas une valeur manquante. Écris NA, sans guillemets."]],
 mots:["missing value"],
