 pieges:[["   Length  N.unique   N.blank Min.nchar Max.nchar ","Une colonne de texte : depuis R 4.6.0, summary compte les valeurs, les valeurs distinctes (N.unique) et les vides (N.blank). Si la colonne devait contenir des nombres, vérifie sa lecture avec str()."]],
 mots:["column","quartile"],
