 defi:{consigne:"Résume la colonne note du tableau classe.", ok:["^summary\\( ?classe\\$note ?\\)$","^summary\\( ?classe\\[\\[ ?([\"'])note\\1 ?\\]\\] ?\\)$"], fautes:[["^summary\\( ?note ?\\)$","note seul n'existe pas : la colonne vit dans le tableau, classe$note."],["^summari[sz]e\\(","Le nom de la fonction est summary."],["^describe\\(","describe n'existe pas dans R de base. La fonction est summary."]], essai:"summary(classe$note)"},
