 reponse:[["(la LED s'allume)","La broche passe à 5 V sur une Uno, à 3,3 V sur les cartes qui fonctionnent en 3,3 V"]],
 pieges:[["error: 'digitalwrite' was not declared in this scope","Le W est en majuscule : digitalWrite."],["error: 'low' was not declared in this scope","HIGH et LOW s'écrivent tout en majuscules."],["(la LED brille à peine)","La broche n'a pas été réglée en OUTPUT dans setup()."]],
