 reponse:[["0","Potentiomètre tourné à fond d'un côté : 0 V"],["1023","À fond de l'autre côté : 5 V"]],
 pieges:[["(des valeurs qui bougent toutes seules)","Rien n'est branché sur l'entrée : la valeur varie au gré de tout, même de ta main près de la carte."],["error: 'analogread' was not declared in this scope","Le R est en majuscule : analogRead."]],
 mots:["pin"],
